import { useState, useEffect } from 'react';

function App() {
  const [items, setItems] = useState<any[]>([]);
  const [name, setName] = useState('');

  useEffect(() => {
    fetch('http://localhost:8000/api/items').then(r => r.json()).then(setItems);
  }, []);

  const addItem = async () => {
    const res = await fetch('http://localhost:8000/api/items', {
      method: 'POST',
      headers: {'Content-Type':'application/json'},
      body: JSON.stringify({id: Date.now(), name})
    });
    const data = await res.json();
    setItems([...items, data]);
    setName('');
  };

  return (
    <div className="p-8 bg-[#0a0a0f] min-h-screen text-white">
      <h1 className="text-2xl font-bold">Fullstack FastAPI + React - P4 Template</h1>
      <p className="text-slate-400">Você cria orientando AI</p>
      <div className="mt-4 flex gap-2">
        <input value={name} onChange={e => setName(e.target.value)} placeholder="Item name" className="px-3 py-2 rounded-lg bg-[#11111b] border border-[#1e1e2e]" />
        <button onClick={addItem} className="px-4 py-2 rounded-lg bg-white text-black">Add</button>
      </div>
      <div className="mt-6 space-y-2">
        {items.map((it:any) => <div key={it.id} className="p-3 rounded-xl bg-[#11111b] border border-[#1e1e2e]">{it.name}</div>)}
      </div>
    </div>
  );
}

export default App;
